import http from 'k6/http';
import { check, sleep } from 'k6';
import { Counter } from 'k6/metrics';

// Load seeded test data generated by loadtest/seed-loadtest.js
const testData = JSON.parse(open('./data.json'));

const doubleBookings = new Counter('double_bookings');
const sqliteBusyErrors = new Counter('sqlite_busy_errors');
const holdSuccesses = new Counter('hold_successes');
const holdConflicts = new Counter('hold_conflicts');
const checkoutSuccesses = new Counter('checkout_successes');

export const options = {
  scenarios: {
    // Scenario 1: 200 VUs racing for 20 seats
    hold_race: {
      executor: 'ramping-vus',
      startVUs: 1,
      stages: [
        { duration: '5s', target: 200 },
        { duration: '15s', target: 200 },
        { duration: '5s', target: 0 },
      ],
      gracefulRampDown: '2s',
      exec: 'runHoldRace',
    },
    // Scenario 2: Mixed browsing, seat map viewing, holding, and checking out
    mixed_scenario: {
      executor: 'ramping-vus',
      startVUs: 1,
      stages: [
        { duration: '5s', target: 50 },
        { duration: '15s', target: 50 },
        { duration: '5s', target: 0 },
      ],
      gracefulRampDown: '2s',
      exec: 'runMixedScenario',
    },
  },
  thresholds: {
    double_bookings: ['count == 0'],
    sqlite_busy_errors: ['count == 0'],
    http_req_failed: ['rate < 0.95'], // Contention naturally yields 409s, but server shouldn't return 500s
  },
};

export function runHoldRace() {
  const vuIndex = (__VU - 1) % testData.tokens.length;
  const token = testData.tokens[vuIndex];

  // Pick 1 random seat from the 20 contention seats
  const seatIdx = Math.floor(Math.random() * testData.raceSeats.length);
  const targetSeat = testData.raceSeats[seatIdx];

  const payload = JSON.stringify({ seatIds: [targetSeat.id] });
  const params = {
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    tags: { name: 'HoldRace' },
  };

  const res = http.post(`${testData.baseUrl}/api/shows/${testData.raceShowId}/hold`, payload, params);

  const isSuccess = res.status === 200;
  const isConflict = res.status === 409;
  const isBusy = res.status === 500 && res.body && res.body.includes('SQLITE_BUSY');

  if (isSuccess) holdSuccesses.add(1);
  if (isConflict) holdConflicts.add(1);
  if (isBusy) sqliteBusyErrors.add(1);

  check(res, {
    'hold returns 200 or 409': (r) => r.status === 200 || r.status === 409,
    'no sqlite busy error': () => !isBusy,
  });

  // Small pacing between race bursts
  sleep(0.05);
}

export function runMixedScenario() {
  const vuIndex = (__VU - 1) % testData.tokens.length;
  const token = testData.tokens[vuIndex];
  const params = {
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
    tags: { name: 'MixedScenario' },
  };

  // 1. Browse catalogue / events
  const eventsRes = http.get(`${testData.baseUrl}/api/events`, params);
  check(eventsRes, { 'browse events returns 200': (r) => r.status === 200 });

  // 2. Fetch live seat map for the mixed show
  const mapRes = http.get(`${testData.baseUrl}/api/shows/${testData.mixedShowId}/seats`, params);
  check(mapRes, { 'seat map returns 200': (r) => r.status === 200 });

  // 3. Select an available seat or fallback to seeded list
  let targetSeatId = null;
  try {
    const body = JSON.parse(mapRes.body);
    const available = body.seats ? body.seats.filter((s) => s.status === 'available') : [];
    if (available.length > 0) {
      targetSeatId = available[Math.floor(Math.random() * available.length)].id;
    }
  } catch {}

  if (!targetSeatId) {
    const fallbackIdx = Math.floor(Math.random() * testData.mixedSeats.length);
    targetSeatId = testData.mixedSeats[fallbackIdx].id;
  }

  // 4. Attempt hold
  const holdPayload = JSON.stringify({ seatIds: [targetSeatId] });
  const holdRes = http.post(`${testData.baseUrl}/api/shows/${testData.mixedShowId}/hold`, holdPayload, params);

  if (holdRes.status === 200) {
    holdSuccesses.add(1);

    // 5. If hold won, attempt checkout
    const checkoutPayload = JSON.stringify({
      showId: testData.mixedShowId,
      guestName: `Customer ${__VU}`,
      guestMobile: '9876543210',
      guestEmail: `vu_${__VU}@seatwise.load`,
    });

    const checkoutRes = http.post(`${testData.baseUrl}/api/bookings`, checkoutPayload, params);

    if (checkoutRes.status === 201) {
      checkoutSuccesses.add(1);
    }

    check(checkoutRes, {
      'checkout completes with 201 or 409': (r) => r.status === 201 || r.status === 409,
      'no unexpected server error': (r) => r.status !== 500,
    });
  } else if (holdRes.status === 409) {
    holdConflicts.add(1);
  }

  sleep(0.1);
}

export function teardown() {
  // Confirm seat maps are accessible post-test
  const raceMap = http.get(`${testData.baseUrl}/api/shows/${testData.raceShowId}/seats`);
  const mixedMap = http.get(`${testData.baseUrl}/api/shows/${testData.mixedShowId}/seats`);

  check(raceMap, { 'teardown: race seat map accessible': (r) => r.status === 200 });
  check(mixedMap, { 'teardown: mixed seat map accessible': (r) => r.status === 200 });
}
